/// through the turbofish slot (e.g. `env_replace_lossy::<SystemEnv>(raw)`).
/// `pacquet-config` threads its own multi-capability `Host` instead.
pub struct SystemEnv;

impl EnvVar for SystemEnv {
    fn var(name: &str) -> Option<String> {
        std::env::var(name).ok()
    }
}

