/// `registry=` of its own to scope them to. Matches pnpm's
/// `npmDefaults.registry`.
const DEFAULT_REGISTRY: &str = "https://registry.npmjs.org/";

/// Config prefix on `npm_config_//host/:_authToken` style env vars.
const NPM_CONFIG_PREFIX: &str = "npm_config_";
/// Config prefix on `pnpm_config_//host/:_authToken` style env vars.
/// Takes precedence over [`NPM_CONFIG_PREFIX`] for the same URL-scoped key.
const PNPM_CONFIG_PREFIX: &str = "pnpm_config_";

/// Strip a leading ASCII `prefix` from `name`, matching case-insensitively,
/// and return the remainder. Returns `None` when `name` does not start with
/// `prefix`.
///
/// The comparison walks bytes rather than slicing `name` as a `str`, so a
/// name containing multi-byte UTF-8 never triggers a non-char-boundary
/// panic. `prefix` is ASCII, so once every prefix byte matches the split
/// index is guaranteed to fall on a char boundary and the remainder slice
/// is valid.
fn strip_config_prefix_ci<'a>(name: &'a str, prefix: &str) -> Option<&'a str> {
    let name_bytes = name.as_bytes();
    let prefix_bytes = prefix.as_bytes();
    if name_bytes.len() < prefix_bytes.len() {
        return None;
    }
    if name_bytes[..prefix_bytes.len()]
        .iter()
        .zip(prefix_bytes)
        .all(|(actual, expected)| actual.eq_ignore_ascii_case(expected))
    {
        Some(&name[prefix_bytes.len()..])
    } else {
        None
    }
